	effectiveHas := false
	if effectiveVersion != 0 {
		for i := len(history) - 1; i >= 0; i-- {
			if history[i].Version.Version == effectiveVersion {
				effectiveHas = history[i].HasValue
				if effectiveHas {
					effectiveValue = json.RawMessage(history[i].Value)
